require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();oecrm_require_permission($conn,'employee_documents','download');$id=oecrm_int_param($_GET,'id');$stmt=mysqli_prepare($conn,'SELECT * FROM employee_documents WHERE id=?');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$doc=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$doc){http_response_code(404);exit('Document not found.');}$path=realpath(__DIR__.'/../storage/employee_documents/'.$doc['stored_name']);$root=realpath(__DIR__.'/../storage/employee_documents');if(!$path||strpos($path,$root)!==0||!is_file($path)){http_response_code(404);exit('Document file not found.');}oecrm_audit($conn,'employee_documents','download','employee_document',$id,'Employee document downloaded');header('Content-Type: '.($doc['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace(['"',"\r","\n"],'',$doc['original_name']).'"');readfile($path);exit;